function trimsUntilUnique(nums: number[]): number {
  let ops = 0;
  for (let start = 0; start < nums.length; start += 3) {
    const rest = nums.slice(start);
    if (new Set(rest).size === rest.length) return ops;
    ops++;
  }
  return ops;
}

