class Solution:
    def trimsUntilUnique(self, nums: List[int]) -> int:
        ops, start = 0, 0
        while start < len(nums):
            rest = nums[start:]
            if len(set(rest)) == len(rest):
                return ops
            ops += 1
            start += 3
        return ops

