function trimsUntilUnique(nums: number[]): number {
  const seen = new Set<number>();
  for (let i = nums.length - 1; i >= 0; i--) {
    if (seen.has(nums[i])) return Math.floor(i / 3) + 1;
    seen.add(nums[i]);
  }
  return 0;
}

